Q: Mocking a context manager A: <p>Another possibility is to use a factory to create an object that implements the context manager interface:</p>
<pre class="lang-py prettyprint-override"><code>import unittest
import unittest.mock
import tempfile


def myfunc():
    with tempfile.NamedTemporaryFile() as mytmp:
        return mytmp.name


def mock_named_temporary_file(tmpname):
    class MockNamedTemporaryFile(object):
        def __init__(self, *args, **kwargs):
            self.name = tmpname

        def __enter__(self):
            return self

        def __exit__(self, type, value, traceback):
            pass

    return MockNamedTemporaryFile()


class TestMock(unittest.TestCase):
    @unittest.mock.patch(&quot;tempfile.NamedTemporaryFile&quot;)
    def test_cm(self, mock_tmp):
        mytmpname = &quot;abcde&quot;
        mock_tmp.return_value = mock_named_temporary_file(mytmpname)
        self.assertEqual(myfunc(), mytmpname)

</code></pre>
